def compute(vars):
    total_unrecognized = vars["v1"] + vars["v2"]
    return {
        "value": total_unrecognized,
        "trace": {
            "unrecognized_stock_options": vars["v1"],
            "unrecognized_rsus": vars["v2"],
            "total_unrecognized": total_unrecognized,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
